/// Migrated from ASP.NET Framework WebForms to ASP.NET Core MVC (.NET 8).
///
/// Patterns replaced:
///   1. Response.End()              → return from action (no equivalent needed)
///   2. Response.Redirect(url,true) → return RedirectResult
///   3. catch (ThreadAbortException)→ removed entirely (no longer thrown)
///   4. Response.Write/Clear/AddHeader → FileContentResult or IActionResult
/// </summary>
public class ReportController : Controller
{
    // Was: btnExport_Click event handler
    // Pattern: ASP.NET request termination (Response.End + Response.Write)
    // Fix: Return a FileContentResult — the framework handles the response lifecycle.
    [HttpPost]
    public IActionResult Export()
    {
        var data = GenerateReport();

        return File(
            System.Text.Encoding.UTF8.GetBytes(data),
            "text/csv",
            "report.csv");
    }

    // Was: btnRedirect_Click event handler
    // Patterns replaced:
    //   - Response.Redirect(url, true) → return Redirect(url)
    //   - catch (ThreadAbortException)  → removed (never thrown in .NET 8)
    [HttpPost]
    public IActionResult ProcessAction()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login");
        }

        try
        {
            ProcessRequest();
            return Redirect("/success");
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

